    /// <summary>按本地名取路径（名字拼错当场抛）。</summary>
    public static string Get(string name) => name switch
    {
        "pen" => pen,
        "penSparkle" => penSparkle,
        "laserTool" => laserTool,
        "edit" => edit,
        "highlight" => highlight,
        "inkStroke" => inkStroke,
        "inkingTool" => inkingTool,
        "calligraphyPen" => calligraphyPen,
        "paintBrush" => paintBrush,
        "paintBrushSparkle" => paintBrushSparkle,
        "wand" => wand,
        "handDraw" => handDraw,
        "drawShape" => drawShape,
        "drawText" => drawText,
        _ => throw new System.ArgumentOutOfRangeException(nameof(name), name, "探测表里没有这个名字"),
    };

    /// <summary>这张网格有多大（24 的不用问，返回 24）。</summary>
    public static float BoxOf(string name) => name switch
    {
        "laserTool" => laserToolBox,
        _ => 24f,
    };
}
